// @ts-nocheck
import { test, expect } from '@playwright/test';
import { signInAs } from '../../../../tests/sample-consumer/frontend/tests/e2e/fixtures/auth';

test.beforeEach(async ({ page, request }) => {
  await signInAs(page, request, 'user');
});

test('cancels pro subscription', async ({ page, request }) => {
  await page.goto('/login');
  await expect(page.getByRole('heading', { name: 'Sign in' })).toBeVisible();

  await page.getByLabel('Email').fill('pro@example.test');
  await page.getByLabel('Password').fill('correct-horse-battery-staple');
  await page.getByRole('button', { name: 'Sign in' }).click();
  await expect(page).toHaveURL(/\/dashboard$/);

  await page.getByRole('link', { name: 'Settings' }).click();
  await expect(page.getByRole('region', { name: 'Subscription' })).toContainText('Pro');

  await page.getByRole('button', { name: 'Cancel subscription' }).click();
  await expect(page.getByRole('dialog', { name: 'Cancel pro plan?' })).toBeVisible();

  await page.getByRole('button', { name: 'Confirm cancel' }).click();
  await expect(page.getByRole('status')).toHaveText('Your plan was downgraded to Free.');

  const me = await request.get('/api/subscriptions/me');
  expect(me.status()).toBe(200);
  expect(await me.json()).toMatchObject({ status: 'canceled' });
});
